[{"order":1,"type":"heading","text":"Production Deployment of Django: Nginx, SSL/TLS, and Static Files"},{"order":2,"type":"paragraph","text":"When deploying a Django application to production, using the built-in development server (python manage.py runserver) is insecure and performs poorly. A robust production stack typically consists of Gunicorn as the WSGI application server, Nginx as a reverse proxy to handle incoming client requests and serve static files directly, and Let's Encrypt for free, automated SSL/TLS certificates."},{"order":3,"type":"subheading","text":"Step 1: Configuring Django for Static Files"},{"order":4,"type":"paragraph","text":"Before configuring Nginx, you must tell Django where to collect all static assets (CSS, JavaScript, images) so that Nginx can read them efficiently without hitting Gunicorn."},{"order":5,"type":"code","text":"# settings.py

STATIC_URL = '/static/'
STATIC_ROOT = '/var/www/example.com/static/'"},{"order":6,"type":"paragraph","text":"Run the collectstatic management command on your server to populate this directory:"},{"order":7,"type":"code","text":"python manage.py collectstatic"},{"order":8,"type":"subheading","text":"Step 2: Configuring Gunicorn"},{"order":9,"type":"paragraph","text":"Gunicorn acts as the WSGI server that communicates with your Django app. Create a systemd service file for Gunicorn to manage its lifecycle."},{"order":10,"type":"code","text":"[Unit]
Description=gunicorn daemon for Django project
After=network.target

[Service]
User=www-data
Group=www-data
WorkingDirectory=/home/user/my_django_project
ExecStart=/home/user/my_django_project/venv/bin/gunicorn \
          --access-logfile - \
          --workers 3 \
          --bind unix:/home/user/my_django_project/my_django_project.sock \
          my_django_project.wsgi:application

[Install]
WantedBy=multi-user.target"},{"order":11,"type":"subheading","text":"Step 3: Configuring Nginx as a Reverse Proxy"},{"order":12,"type":"paragraph","text":"Nginx sits in front of Gunicorn. It intercepts client requests, serves static files natively, and proxies dynamic requests to the Gunicorn UNIX socket."},{"order":13,"type":"code","text":"server {
    listen 80;
    server_name example.com www.example.com;

    location = /favicon.ico { access_log off; log_not_found off; }

    location /static/ {
        alias /var/www/example.com/static/;
    }

    location / {
        include proxy_params;
        proxy_pass http://unix:/home/user/my_django_project/my_django_project.sock;
    }
}"},{"order":14,"type":"subheading","text":"Step 4: Securing with SSL/TLS via Certbot"},{"order":15,"type":"paragraph","text":"To enable HTTPS, use Certbot to automatically obtain and configure a Let's Encrypt SSL certificate for your Nginx server block."},{"order":16,"type":"code","text":"sudo apt install certbot python3-certbot-nginx
sudo certbot --nginx -d example.com -d www.example.com"},{"order":17,"type":"paragraph","text":"Certbot will automatically modify your Nginx configuration to listen on port 443 with SSL enabled and add redirection rules from HTTP to HTTPS."},{"order":18,"type":"subheading","text":"Step 5: Updating Django Settings for HTTPS"},{"order":19,"type":"paragraph","text":"Once SSL is active, ensure your Django production settings enforce secure cookies and HTTPS connections."},{"order":20,"type":"code","text":"# settings.py (Production)

SECURE_SSL_REDIRECT = True
SESSION_COOKIE_SECURE = True
CSRF_COOKIE_SECURE = True
SECURE_HSTS_SECONDS = 31536000
SECURE_HSTS_INCLUDE_SUBDOMAINS = True
SECURE_HSTS_PRELOAD = True
SECURE_PROXY_SSL_HEADER = ('HTTP_X_FORWARDED_PROTO', 'https')"},{"order":21,"type":"bullet_point","text":"SECURE_SSL_REDIRECT ensures all HTTP traffic is redirected to HTTPS."},{"order":22,"type":"bullet_point","text":"SECURE_PROXY_SSL_HEADER tells Django to trust Nginx proxy headers when determining if a request is secure."}]
